package org.kanger;
import java.util.*;
import org.kanger.ContextDependentCutInspection.*;
/** QA-only access to exact received-ticket selection and independent continued native replay. */
public final class ContextDependentRuntimeContinuationAuditProbe {
    public static int index(ContextDependentRuntimeBarrierInspection.Result result,String cut,int output){ContextDependentRoundInspection.Barrier last=result.checked.barriers.get(result.checked.barriers.size()-1);ContextDependentRoundInspection.Ticket target=result.outputTickets.get(output);List<ContextDependentRoundInspection.Ticket> common=new ArrayList<>(last.common);int at=common.indexOf(target);if(at>=0)return at;int ordinal=0;for(int r=0;r<result.history.size();r++)for(String owner:last.cuts.keySet())for(int p=0;p<result.history.get(r).recipes.get(owner).size();p++){ContextDependentRoundInspection.Ticket t=new ContextDependentRoundInspection.Ticket(r,owner,p);if(owner.equals(cut)||r<result.history.size()-1&&last.common.contains(t)){if(t.equals(target))return common.size()+ordinal;ordinal++;}}throw new AssertionError("Target proof is not visible in exact receiving cut");}
    public static void audit(Member child,List<Cut> cuts,ContextDependentRuntimeContinuationInspection.Result result,ContextDependentRuntimeContinuationInspection.Request request)throws Exception{ContextDependentIterationInspection.Request p=request.first.execution.preparation.projection.qualification.append.iteration;ContextDependentRuntimeBarrierInspection.replay(child,cuts,new ContextDependentRoundInspection.Request(p.policy,p.capacity,result.first.history),result.first.checked,result.input,request.next.execution.steps,result.outputs,request.next.bridgeWork);}
    public static void corrupt(Member child,List<Cut> cuts,ContextDependentRuntimeContinuationInspection.Result result,ContextDependentRuntimeContinuationInspection.Request request,String mode)throws Exception{Object target=result.outputs.get(0),value;String field;if(mode.equals("sources")){field="sources";Set<ContextProductionCapture.Source> sources=new LinkedHashSet<>(result.outputs.get(0).sources);sources.remove(sources.iterator().next());value=Collections.unmodifiableSet(sources);}else if(mode.equals("depth")){field="depth";value=result.outputs.get(0).depth+1;}else if(mode.equals("function")){ContextDependentRuntimeExecution.Node fn=null;for(ContextDependentRuntimeExecution.Node n:result.outputs.get(0).nodes)if(n.function!=null&&n.arguments.size()>1){fn=n;break;}if(fn==null)throw new AssertionError("Multi-coordinate function fixture required");target=fn;field="arguments";List<Integer> args=new ArrayList<>(fn.arguments);Collections.swap(args,0,1);value=Collections.unmodifiableList(args);}else throw new AssertionError("Unknown continued corruption");java.lang.reflect.Field f=target.getClass().getDeclaredField(field);f.setAccessible(true);Object previous=f.get(target);try{f.set(target,value);audit(child,cuts,result,request);}finally{f.set(target,previous);}}
}
